    const finalProjectId = projectId || `proj_${Date.now()}`
    const existing = projectStore.getProject(finalProjectId, userId)

    const indexed = await indexCodebase(
      resolvedRoot,
      finalProjectId,
      userId,
      params.name,
      existing || undefined
