function parseJsTsFile(
  filePath: string,
  lines: string[],
  language: string,
  chunks: CodeChunk[],
  symbols: SymbolDef[]
) {
  const funcRegex =
    /^(?:export\s+)?(?:async\s+)?(?:function\*?\s+([a-zA-Z0-9_$]+)|(?:const|let|var)\s+([a-zA-Z0-9_$]+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>|(?:const|let|var)\s+([a-zA-Z0-9_$]+)\s*=\s*function)/
  const classRegex = /^(?:export\s+)?(?:abstract\s+)?class\s+([a-zA-Z0-9_$]+)/
  const interfaceRegex = /^(?:export\s+)?interface\s+([a-zA-Z0-9_$]+)/
  const typeRegex = /^(?:export\s+)?type\s+([a-zA-Z0-9_$]+)\s*=/

  let i = 0
  while (i < lines.length) {
    const rawLine = lines[i]
    const trimmed = rawLine.trim()

    // Match Classes
    const classMatch = trimmed.match(classRegex)
    if (classMatch) {
      const name = classMatch[1]
      const { endLine, blockContent } = extractBraceBlock(lines, i)
      symbols.push({
        name,
        kind: 'class',
        filePath,
        line: i + 1,
        signature: trimmed
      })
      chunks.push({
        id: `${filePath}#class:${name}:L${i + 1}`,
        filePath,
        startLine: i + 1,
        endLine,
        content: blockContent,
        type: 'class',
        symbolName: name,
        language,
        hash: computeSha256(blockContent)
      })
      i = endLine
      continue
    }

    // Match Interfaces
    const interfaceMatch = trimmed.match(interfaceRegex)
    if (interfaceMatch) {
      const name = interfaceMatch[1]
      const { endLine, blockContent } = extractBraceBlock(lines, i)
      symbols.push({
        name,
        kind: 'interface',
        filePath,
        line: i + 1,
        signature: trimmed
      })
      chunks.push({
        id: `${filePath}#interface:${name}:L${i + 1}`,
        filePath,
        startLine: i + 1,
        endLine,
        content: blockContent,
        type: 'interface',
        symbolName: name,
        language,
        hash: computeSha256(blockContent)
      })
      i = endLine
      continue
    }

    // Match Types
    const typeMatch = trimmed.match(typeRegex)
    if (typeMatch) {
      const name = typeMatch[1]
      let end = i
      while (end < lines.length && !lines[end].includes(';') && end - i < 20) {
        end++
      }
      const endLine = Math.min(end + 1, lines.length)
      const blockContent = lines.slice(i, endLine).join('\n')
      symbols.push({
        name,
        kind: 'type',
        filePath,
        line: i + 1,
        signature: trimmed
      })
      chunks.push({
        id: `${filePath}#type:${name}:L${i + 1}`,
        filePath,
        startLine: i + 1,
        endLine,
        content: blockContent,
        type: 'interface',
        symbolName: name,
        language,
        hash: computeSha256(blockContent)
      })
      i = endLine
      continue
    }

    // Match Functions
    const funcMatch = trimmed.match(funcRegex)
    if (funcMatch) {
      const name = funcMatch[1] || funcMatch[2] || funcMatch[3]
      const { endLine, blockContent } = extractBraceBlock(lines, i)
      symbols.push({
        name,
        kind: 'function',
        filePath,
        line: i + 1,
        signature: trimmed
      })
      chunks.push({
        id: `${filePath}#func:${name}:L${i + 1}`,
        filePath,
        startLine: i + 1,
        endLine,
        content: blockContent,
        type: 'function',
        symbolName: name,
        language,
        hash: computeSha256(blockContent)
      })
      i = endLine
      continue
    }

    i++
  }
}

export interface OrchestrationResult {
  role: SpecializedAgentRole
  agentName: string
  traceId: string
  systemInstruction: string
  sanitizedPrompt: string
  privacyMinimization: {
    applied: boolean
    redactedTypes: string[]
  }
}

export class BrowserUseAgent {
  private sessions = new Map<string, BrowserAgentSession>()

  /**
   * Starts or resumes a browser session
   */
  public getOrCreateSession(sessionId = 'default'): BrowserAgentSession {
    if (!this.sessions.has(sessionId)) {
      this.sessions.set(sessionId, {
        id: sessionId,
        currentUrl: '',
        history: [],
        pageTitle: '',
        extractedText: '',
        status: 'idle'
      })
    }
    return this.sessions.get(sessionId)!
  }

  /**
   * Executes a browser action with security check and recovery
   */
  public async executeAction(
    action: BrowserAction,
    sessionId = 'default'
  ): Promise<BrowserActionResult> {
    const session = this.getOrCreateSession(sessionId)
    const startTime = Date.now()

    try {
      switch (action.type) {
        case 'navigate': {
          if (!action.url) {
            return {
              success: false,
              action: 'navigate',
              error: 'URL is required for navigation',
              executionTimeMs: Date.now() - startTime
            }
          }

          // 1. SSRF Validation (Cybersecurity Skill)
          const ssrfCheck = cybersecurity.validateUrlForSSRF(action.url)
          if (!ssrfCheck.safe) {
            return {
              success: false,
              action: 'navigate',
              error: `Security violation: ${ssrfCheck.reason}`,
              executionTimeMs: Date.now() - startTime
            }
          }

          session.status = 'navigating'

          // 2. Fetch and extract page using Reader with timeout recovery
          const page = await searchOrchestrator.browseUrl(action.url, 4000)

          // 3. Privacy redaction on extracted content
          const sanitizedContent = privacyAlign.sanitize(page.content).redactedText

          session.currentUrl = action.url
          session.history.push(action.url)
          session.pageTitle = page.title
          session.extractedText = sanitizedContent
          session.status = 'completed'

          return {
            success: Boolean(page && (page.content || page.title)),
            action: 'navigate',
            url: action.url,
            title: page.title,
            content: sanitizedContent,
            executionTimeMs: Date.now() - startTime
          }
        }

        case 'extract_content': {
          if (!session.currentUrl) {
            return {
              success: false,
              action: 'extract_content',
              error: 'No active webpage. Navigate to a URL first.',
              executionTimeMs: Date.now() - startTime
            }
          }

          return {
            success: true,
            action: 'extract_content',
            url: session.currentUrl,
            title: session.pageTitle,
            content: session.extractedText,
            executionTimeMs: Date.now() - startTime
          }
        }

        case 'scroll': {
          session.status = 'interacting'
          // Simulation of scroll in extracted document context
          return {
            success: true,
            action: 'scroll',
            url: session.currentUrl,
            content: `Scrolled ${action.direction || 'down'} ${action.pixels || 500}px in document.`,
            executionTimeMs: Date.now() - startTime
          }
        }

        default:
          return {
            success: false,
            action: action.type,
            error: `Unsupported browser action in headless environment: ${action.type}`,
            executionTimeMs: Date.now() - startTime
          }
      }
    } catch (err: any) {
      session.status = 'failed'
      return {
        success: false,
        action: action.type,
        error: `Browser execution failed: ${err?.message || 'Unknown error'}. Initiating recovery.`,
        executionTimeMs: Date.now() - startTime
      }
    }
  }
}
